// =================================================================
// Mobile Menu Toggle
// =================================================================
const mobileMenuBtn = document.getElementById('mobile-menu-btn');
const mobileNav = document.getElementById('mobile-nav');

if (mobileMenuBtn && mobileNav) {
    const mobileDropdowns = mobileNav.querySelectorAll('.mobile-dropdown');
    const mobileDropdownToggles = mobileNav.querySelectorAll('.mobile-dropdown-toggle');

    function closeMobileDropdowns() {
        mobileDropdowns.forEach(dropdown => {
            dropdown.classList.remove('active');
            const toggle = dropdown.querySelector('.mobile-dropdown-toggle');
            if (toggle) {
                toggle.setAttribute('aria-expanded', 'false');
            }
        });
    }

    mobileDropdownToggles.forEach(toggle => {
        toggle.addEventListener('click', () => {
            const dropdown = toggle.closest('.mobile-dropdown');
            const isOpen = dropdown && dropdown.classList.contains('active');

            closeMobileDropdowns();

            if (!isOpen && dropdown) {
                dropdown.classList.add('active');
                toggle.setAttribute('aria-expanded', 'true');
            }
        });
    });

    function syncMobileNavState() {
        const isOpen = mobileNav.classList.contains('active');
        mobileMenuBtn.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
        mobileNav.setAttribute('aria-hidden', isOpen ? 'false' : 'true');
        document.body.style.overflow = isOpen ? 'hidden' : '';
        if (!isOpen) {
            closeMobileDropdowns();
        }
    }

    // Ensure ARIA state is correct on initial load.
    syncMobileNavState();

    mobileMenuBtn.addEventListener('click', () => {
        mobileNav.classList.toggle('active');
        syncMobileNavState();
    });

    // Close mobile menu when clicking outside
    document.addEventListener('click', (e) => {
        if (!mobileNav.contains(e.target) && !mobileMenuBtn.contains(e.target)) {
            if (mobileNav.classList.contains('active')) {
                mobileNav.classList.remove('active');
                syncMobileNavState();
            }
        }
    });

    // Close mobile menu on window resize
    window.addEventListener('resize', () => {
        if (window.innerWidth > 768 && mobileNav.classList.contains('active')) {
            mobileNav.classList.remove('active');
            syncMobileNavState();
        }
    });
}

// =================================================================
// Desktop Nav Offset Sync (Top Bar + Fixed Nav)
// =================================================================
function initDesktopNavOffset() {
    const topBar = document.querySelector('body:not(.home-page) .top-bar');
    const nav = document.querySelector('body:not(.home-page) .top-bar + nav');
    if (!topBar || !nav) return;

    const syncNavOffset = () => {
        // On mobile the top bar is hidden, so nav should sit at the viewport top.
        if (window.innerWidth <= 768) {
            nav.style.top = '0px';
            return;
        }

        const rect = topBar.getBoundingClientRect();
        const visibleTopBar = Math.max(0, Math.min(rect.bottom, rect.height));
        nav.style.top = `${Math.round(visibleTopBar)}px`;
    };

    syncNavOffset();
    window.addEventListener('scroll', syncNavOffset, { passive: true });
    window.addEventListener('resize', syncNavOffset);
}

initDesktopNavOffset();

// =================================================================
// Cloudflare Email Decode Fallback
// =================================================================
function decodeCloudflareEmail(encoded) {
    if (!encoded || encoded.length < 4) return '';
    const key = parseInt(encoded.slice(0, 2), 16);
    if (Number.isNaN(key)) return '';

    let email = '';
    for (let i = 2; i < encoded.length; i += 2) {
        const hex = encoded.slice(i, i + 2);
        const value = parseInt(hex, 16);
        if (Number.isNaN(value)) return '';
        email += String.fromCharCode(value ^ key);
    }
    return email;
}

function initEmailDecodeFallback() {
    const protectedEmailNodes = document.querySelectorAll('.__cf_email__');
    if (protectedEmailNodes.length === 0) return;

    const fallbackEmail = 'support@brightedgeit.com.au';

    protectedEmailNodes.forEach(node => {
        const encoded = node.getAttribute('data-cfemail');
        const decoded = decodeCloudflareEmail(encoded);
        const email = decoded || fallbackEmail;

        node.textContent = email;

        const anchor = node.closest('a');
        if (anchor && anchor.getAttribute('href')?.includes('/cdn-cgi/l/email-protection')) {
            anchor.setAttribute('href', `mailto:${email}`);
        }
    });

    // Repair any protected links that did not include a cf_email span.
    document.querySelectorAll('a[href*="/cdn-cgi/l/email-protection"]').forEach(link => {
        if (!link.getAttribute('href')?.startsWith('mailto:')) {
            link.setAttribute('href', `mailto:${fallbackEmail}`);
        }
    });
}

initEmailDecodeFallback();

// =================================================================
// Reveal Animations on Scroll
// =================================================================
function reveal() {
    const reveals = document.querySelectorAll(".reveal");
    const windowHeight = window.innerHeight;
    const elementVisible = 150;

    reveals.forEach(element => {
        const elementTop = element.getBoundingClientRect().top;
        if (elementTop < windowHeight - elementVisible) {
            element.classList.add("active");
        }
    });
}

window.addEventListener("load", reveal);
window.addEventListener("scroll", reveal, { passive: true });

// =================================================================
// FAQ Accordion Functionality
// =================================================================
function initFAQ() {
    const faqItems = document.querySelectorAll('.faq-item');

    faqItems.forEach(item => {
        const question = item.querySelector('.faq-question');
        const answer = item.querySelector('.faq-answer');

        if (!question || !answer) return;

        question.addEventListener('click', () => {
            const isOpen = item.classList.contains('active');

            // Close all other FAQs
            faqItems.forEach(otherItem => {
                if (otherItem !== item) {
                    otherItem.classList.remove('active');
                    const otherQuestion = otherItem.querySelector('.faq-question');
                    const otherAnswer = otherItem.querySelector('.faq-answer');
                    if (otherQuestion) otherQuestion.setAttribute('aria-expanded', 'false');
                    if (otherAnswer) otherAnswer.style.maxHeight = '0';
                }
            });

            // Toggle current FAQ
            if (!isOpen) {
                item.classList.add('active');
                question.setAttribute('aria-expanded', 'true');
                answer.style.maxHeight = answer.scrollHeight + 'px';
            } else {
                item.classList.remove('active');
                question.setAttribute('aria-expanded', 'false');
                answer.style.maxHeight = '0';
            }
        });

        // Keyboard accessibility
        question.addEventListener('keydown', (e) => {
            if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                question.click();
            }
        });
    });
}

