function initServiceModals() {
    const modal = document.getElementById('service-modal');
    const modalTitle = document.getElementById('modal-title');
    const modalDesc = document.getElementById('modal-desc');
    const modalList = document.getElementById('modal-list');
    const closeModalBtn = document.querySelector('.modal-close');

    if (!modal || !modalTitle || !modalDesc || !modalList) return;

    // Handle service card clicks
    document.addEventListener('click', (e) => {
        const serviceCard = e.target.closest('.service-card');
        if (serviceCard) {
            const serviceName = serviceCard.getAttribute('data-service');
            const data = serviceData[serviceName];

            if (data) {
                e.preventDefault();
                modalTitle.textContent = data.title;
                modalDesc.textContent = data.desc;
                modalList.innerHTML = data.features.map(f => `<li>${f}</li>`).join('');

                const existingButton = modalList.parentElement.querySelector('.modal-details-btn');
                if (existingButton) {
                    existingButton.remove();
                }

                const detailsLink = serviceDetailLinks[serviceName];
                if (detailsLink) {
                    const detailsButton = document.createElement('a');
                    detailsButton.href = detailsLink;
                    detailsButton.className = 'cta-btn modal-details-btn';
                    detailsButton.textContent = 'View Full Details';
                    detailsButton.style.marginTop = '20px';
                    detailsButton.style.display = 'inline-block';
                    modalList.parentElement.appendChild(detailsButton);
                }

                modal.classList.add('active');
                document.body.style.overflow = 'hidden';
            }
        }
    });

    // Close modal
    function closeModal() {
        modal.classList.remove('active');
        document.body.style.overflow = '';
        // Remove any dynamically added buttons
        const existingButton = modalList.parentElement.querySelector('.modal-details-btn');
        if (existingButton) {
            existingButton.remove();
        }
    }

    if (closeModalBtn) {
        closeModalBtn.addEventListener('click', closeModal);
    }

    // Close on background click
    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            closeModal();
        }
    });

    // Close on Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape' && modal.classList.contains('active')) {
            closeModal();
        }
    });
}

// =================================================================
// Contact Form Validation & Submission
// =================================================================
function initContactForm() {
    const contactForm = document.getElementById('contact-form');
    if (!contactForm) return;

    const formSuccess = document.getElementById('form-success');
    let formError = document.getElementById('form-error');
    if (!formError) {
        formError = document.createElement('div');
        formError.id = 'form-error';
        formError.className = 'form-error';
        formError.setAttribute('role', 'alert');
        formError.setAttribute('aria-live', 'assertive');
        formError.tabIndex = -1;
        if (formSuccess) formSuccess.after(formError); else contactForm.append(formError);
    }

    const showFormError = message => {
        formError.textContent = message;
        formError.classList.add('active');
        formError.focus();
    };
    const clearFormError = () => {
        formError.textContent = '';
        formError.classList.remove('active');
    };
    let isSubmitting = false;

    // Real-time validation
    const inputs = contactForm.querySelectorAll('input[required], textarea[required], select[required]');
    inputs.forEach(input => {
        input.addEventListener('blur', () => validateField(input));
        input.addEventListener('input', () => {
            if (input.classList.contains('error')) {
                validateField(input);
            }
        });
    });

    contactForm.addEventListener('submit', async e => {
        e.preventDefault();
        if (isSubmitting) return;
        clearFormError();

        // Validate all fields
        let isValid = true;
        inputs.forEach(input => {
            if (!validateField(input)) {
                isValid = false;
            }
        });

        // Check privacy checkbox
        const privacyCheckbox = document.getElementById('privacy');
        if (privacyCheckbox && !privacyCheckbox.checked) {
            showError('privacy', 'You must agree to the privacy policy');
            isValid = false;
        } else {
            hideError('privacy');
        }

        if (!isValid) {
            const firstInvalid = contactForm.querySelector('.error');
            if (firstInvalid) firstInvalid.focus();
            return;
        }

        const formData = new FormData(contactForm);
        const turnstileToken = formData.get('cf-turnstile-response');
        if (!turnstileToken) {
            showFormError('Please complete the spam check before sending your message.');
            return;
        }

        const submitBtn = contactForm.querySelector('.submit-btn');
        if (!submitBtn) return;
        const originalText = submitBtn.textContent;
        isSubmitting = true;
        submitBtn.textContent = 'Sending...';
        submitBtn.disabled = true;

        try {
            const response = await fetch("/api/contact", {
                method: "POST",
                headers: { "Content-Type": "application/x-www-form-urlencoded" },
                body: new URLSearchParams(formData).toString()
            });
            if (!response.ok) {
                let errorMessage = 'Unable to send your message. Please try again.';
                try {
                    const errorBody = await response.json();
                    if (errorBody && typeof errorBody.error === 'string') errorMessage = errorBody.error;
                } catch {
                    // Use the safe generic message when the response is not JSON.
                }
                throw new Error(errorMessage);
            }

            if (formSuccess) {
                formSuccess.classList.add('active');
                formSuccess.focus();
                setTimeout(() => formSuccess.classList.remove('active'), 5000);
            }
            contactForm.reset();
        } catch (error) {
            if (formSuccess) formSuccess.classList.remove('active');
            showFormError(error && error.message ? error.message : 'Unable to send your message. Please try again.');
        } finally {
            submitBtn.textContent = originalText;
            submitBtn.disabled = false;
            isSubmitting = false;
        }
    });
}

function validateField(field) {
    const fieldId = field.id;
    const value = field.value.trim();

    // Clear previous errors
    hideError(fieldId);
    field.classList.remove('error');

    // Required field validation
    if (field.hasAttribute('required') && !value) {
        showError(fieldId, field.tagName === 'SELECT' ? 'Please select an option' : `Please enter your ${field.name}`);
        field.classList.add('error');
        return false;
    }

    // Email validation
    if (field.type === 'email' && value) {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailRegex.test(value)) {
            showError(fieldId, 'Please enter a valid email address');
            field.classList.add('error');
            return false;
        }
    }

    // Select validation
    if (field.tagName === 'SELECT' && (!value || value === '')) {
        showError(fieldId, 'Please select an option');
        field.classList.add('error');
        return false;
    }

    return true;
}

function showError(fieldId, message) {
    const errorElement = document.getElementById(`${fieldId}-error`);
    if (errorElement) {
        errorElement.textContent = message;
        errorElement.classList.add('active');
    }
}

function hideError(fieldId) {
    const errorElement = document.getElementById(`${fieldId}-error`);
    if (errorElement) {
        errorElement.classList.remove('active');
    }
}

