// =================================================================
// Optimized Unified Scroll Handler
// =================================================================
function updateSidebarActiveState() {
    const tocLinks = document.querySelectorAll('.toc-link');
    const sections = document.querySelectorAll('.service-section');
    if (tocLinks.length === 0 || sections.length === 0) return;

    let current = '';

    sections.forEach(section => {
        const sectionTop = section.offsetTop;
        if (window.pageYOffset >= sectionTop - 150) {
            current = section.getAttribute('id');
        }
    });

    tocLinks.forEach(link => {
        link.classList.remove('active');
        const linkHref = link.getAttribute('href');
        if (linkHref && linkHref.startsWith('#') && linkHref.slice(1) === current) {
            link.classList.add('active');
        }
    });
}

// Unified scroll handler
const unifiedScrollHandler = debounce(() => {
    reveal();
    updateSidebarActiveState();
}, 50);

// Unified scroll handler combines reveal and sidebar state updates
window.addEventListener('scroll', unifiedScrollHandler, { passive: true });

// =================================================================
// Network Canvas Animation
// =================================================================
function initNetworkCanvas() {
    if (!document.body.classList.contains('home-page')) return;
    const canvas = document.getElementById("networkCanvas");
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    const hero = canvas.parentElement;
    let width = 0;
    let height = 0;
    let dpr = 1;
    let particles = [];

    // Optimization: State flags
    let isAnimating = false;
    let isIntersecting = false;
    let lastTime = 0;
    const fpsInterval = 1000 / 30; // Limit to 30 FPS for performance

    // Check reduced motion preference
    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');

    // Color system from CSS variables (no hardcoded RGB)
    const rootStyles = getComputedStyle(document.documentElement);
    const brandPrimary = rootStyles.getPropertyValue('--color-brand-primary').trim();
    const textMuted = rootStyles.getPropertyValue('--color-text-muted').trim();
    const nodeColor = brandPrimary || getComputedStyle(document.body).color;
    const lineColor = textMuted || nodeColor;

    // Configuration
    const connectionDistance = 160;
    const baseSpeed = 0.55;
    const maxSpeed = 0.95;
    const interactionRadius = 140;
    const interactionStrength = 0.035;
    const pulseAmplitude = 0.18;
    const wanderStrength = 0.020;
    const wanderSpeed = 0.75;
    const edgeFadeDistance = 140;

    const mouse = { x: 0, y: 0, active: false };

    class Particle {
        constructor() {
            this.reset();
        }
        reset() {
            this.x = Math.random() * width;
            this.y = Math.random() * height;
            const angle = Math.random() * Math.PI * 2;
            this.depth = 0.7 + Math.random() * 0.6;
            const speed = baseSpeed * this.depth * (0.6 + Math.random() * 0.8);
            this.vx = Math.cos(angle) * speed;
            this.vy = Math.sin(angle) * speed;
            this.baseSize = Math.random() * 1.8 + 1.0;
            this.pulseSpeed = 0.6 + Math.random() * 0.8;
            this.pulsePhase = Math.random() * Math.PI * 2;
            this.wanderPhase = Math.random() * Math.PI * 2;
        }
        update() {
            // Individual wandering (AI vibe: more alive, less uniform)
            const tt = performance.now() * 0.001 * wanderSpeed + this.wanderPhase;
            this.vx += Math.sin(tt) * wanderStrength;
            this.vy += Math.cos(tt) * wanderStrength;

            if (mouse.active) {
                const dx = this.x - mouse.x;
                const dy = this.y - mouse.y;
                const dist = Math.hypot(dx, dy);
                if (dist < interactionRadius && dist > 0.01) {
                    const force = (1 - dist / interactionRadius) * interactionStrength;
                    this.vx += (dx / dist) * force;
                    this.vy += (dy / dist) * force;
                }
            }

            this.x += this.vx;
            this.y += this.vy;

            // Bounce off edges
            if (this.x < 0 || this.x > width) this.vx *= -1;
            if (this.y < 0 || this.y > height) this.vy *= -1;

            // Subtle damping + speed clamp
            this.vx *= 0.99;
            this.vy *= 0.99;
            const speed = Math.hypot(this.vx, this.vy);
            if (speed > maxSpeed) {
                this.vx = (this.vx / speed) * maxSpeed;
                this.vy = (this.vy / speed) * maxSpeed;
            }
        }
        draw(t, allowPulse, edgeFade) {
            const pulse = allowPulse ? Math.sin(t * this.pulseSpeed + this.pulsePhase) : 0;
            const size = this.baseSize * this.depth * (1 + pulse * pulseAmplitude);
            const fade = edgeFade === undefined ? 1 : edgeFade;
            const alpha = (0.68 + pulse * 0.10) * fade;
            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.arc(this.x, this.y, size, 0, Math.PI * 2);
            ctx.fill();
        }
    }

    function computeParticleCount(w, h) {
        const area = w * h;
        let count = Math.round(area / 9000);
        if (window.innerWidth <= 768) {
            count = Math.round(count * 0.7);
        }
        return Math.max(45, Math.min(120, count));
    }

    function rebuildParticles(count) {
        particles = [];
        for (let i = 0; i < count; i++) {
            particles.push(new Particle());
        }
    }

    // Resize handling + DPR scaling
    function resize() {
        const rect = hero.getBoundingClientRect();
        width = rect.width;
        height = rect.height;
        if (!width || !height) return;

        dpr = window.devicePixelRatio || 1;
        canvas.width = Math.round(width * dpr);
        canvas.height = Math.round(height * dpr);
        canvas.style.width = `${width}px`;
        canvas.style.height = `${height}px`;
        ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

        const targetCount = computeParticleCount(width, height);
        if (particles.length !== targetCount) {
            rebuildParticles(targetCount);
        }
    }
    window.addEventListener("resize", resize);

    // Mouse tracking (very light interaction)
    hero.addEventListener('pointermove', (e) => {
        const rect = canvas.getBoundingClientRect();
        mouse.x = e.clientX - rect.left;
        mouse.y = e.clientY - rect.top;
        mouse.active = true;
    }, { passive: true });

    hero.addEventListener('pointerleave', () => {
        mouse.active = false;
    }, { passive: true });

    function getEdgeFade(particle) {
        const edge = Math.min(
            particle.x,
            width - particle.x,
            particle.y,
            height - particle.y
        );
        return Math.max(0, Math.min(1, edge / edgeFadeDistance));
    }

    function drawScene(currentTime) {
        if (!width || !height) return;
        const allowMotion = !prefersReducedMotion.matches;
        const time = allowMotion ? (currentTime || performance.now()) * 0.001 : 0;

        ctx.clearRect(0, 0, width, height);
        ctx.fillStyle = nodeColor;
        ctx.strokeStyle = lineColor;
        ctx.lineWidth = 1.1;

        particles.forEach((p) => {
            if (allowMotion) {
                p.update();
            }
            p.edgeFade = getEdgeFade(p);
        });

        particles.forEach((p, index) => {
            p.draw(time, allowMotion, p.edgeFade);

            for (let j = index + 1; j < particles.length; j++) {
                const p2 = particles[j];
                const dist = Math.hypot(p.x - p2.x, p.y - p2.y);
                if (dist < connectionDistance) {
                    const alpha = (1 - dist / connectionDistance) * 0.20 * Math.min(p.edgeFade, p2.edgeFade);
                    ctx.globalAlpha = alpha;
                    ctx.beginPath();
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.stroke();
                }
            }
        });

        ctx.globalAlpha = 1;
    }

    function animate(currentTime) {
        if (!isAnimating) return;

        requestAnimationFrame(animate);

        const elapsed = currentTime - lastTime;
        if (elapsed < fpsInterval) return;

        lastTime = currentTime - (elapsed % fpsInterval);

        drawScene(currentTime);
    }

    function startIfAllowed() {
        if (prefersReducedMotion.matches) return;
        if (!isIntersecting || document.visibilityState !== 'visible') return;
        if (!isAnimating) {
            isAnimating = true;
            lastTime = performance.now();
            animate(lastTime);
        }
    }

    // Performance & Accessibility Observer
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            isIntersecting = entry.isIntersecting;
            if (isIntersecting) {
                startIfAllowed();
            } else {
                isAnimating = false;
            }
        });
    }, { threshold: 0 });

    observer.observe(canvas);

    // Pause when tab is hidden
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'hidden') {
            isAnimating = false;
        } else {
            startIfAllowed();
        }
    });

    prefersReducedMotion.addEventListener('change', () => {
        if (prefersReducedMotion.matches) {
            isAnimating = false;
            drawScene(performance.now());
        } else {
            startIfAllowed();
        }
    });

    resize();
    drawScene(performance.now());
}

function scheduleNetworkCanvasInit() {
    if (!document.body.classList.contains('home-page')) return;
    const start = () => initNetworkCanvas();
    if ('requestIdleCallback' in window) {
        window.requestIdleCallback(() => requestAnimationFrame(start), { timeout: 200 });
    } else {
        requestAnimationFrame(() => setTimeout(start, 150));
    }
}

// =================================================================
// Global Services Mega Menu
// =================================================================
function initGlobalServicesMenu() {
    const menuItem = document.querySelector('.services-menu-item');
    const trigger = document.getElementById('services-menu-trigger');
    const menu = document.getElementById('services-mega-menu');

    if (!menuItem || !trigger || !menu) return;

    const isDesktop = () => window.matchMedia('(min-width: 769px)').matches;
    let closeTimer;
    const cancelClose = () => {
        if (closeTimer) window.clearTimeout(closeTimer);
        closeTimer = undefined;
    };
    const setOpen = (open) => {
        if (open) cancelClose();
        menuItem.classList.toggle('is-open', open);
        trigger.setAttribute('aria-expanded', open ? 'true' : 'false');
    };
    const closeAfterDelay = () => {
        cancelClose();
        closeTimer = window.setTimeout(() => setOpen(false), 280);
    };

    trigger.addEventListener('click', () => {
        if (trigger.tagName === 'BUTTON') setOpen(!menuItem.classList.contains('is-open'));
    });
    menuItem.addEventListener('mouseenter', () => { if (isDesktop()) { cancelClose(); setOpen(true); } });
    menuItem.addEventListener('mouseleave', () => { if (isDesktop()) closeAfterDelay(); });

    document.addEventListener('click', (event) => {
        if (!menuItem.contains(event.target)) setOpen(false);
    });

    document.addEventListener('keydown', (event) => {
        if (event.key !== 'Escape') return;
        const wasOpen = menuItem.classList.contains('is-open');
        setOpen(false);
        if (wasOpen) trigger.focus();

        if (mobileNav && mobileNav.classList.contains('active')) {
            mobileNav.classList.remove('active');
            mobileNav.setAttribute('aria-hidden', 'true');
            if (mobileMenuBtn) mobileMenuBtn.setAttribute('aria-expanded', 'false');
            document.body.style.overflow = '';
            mobileNav.querySelectorAll('.mobile-dropdown').forEach(dropdown => {
                dropdown.classList.remove('active');
                dropdown.querySelector('.mobile-dropdown-toggle')?.setAttribute('aria-expanded', 'false');
            });
            mobileMenuBtn?.focus();
        }
    });

    window.addEventListener('resize', () => { if (!isDesktop()) setOpen(false); });
}

async function initTurnstile() {
    const widgets = Array.from(document.querySelectorAll('.cf-turnstile[data-sitekey]'));
    if (!widgets.length) return;

    let sitekey = widgets[0].dataset.sitekey;
    if (!sitekey || sitekey === 'REPLACE_WITH_TURNSTILE_SITEKEY') {
        try {
            const response = await fetch('/api/config', { cache: 'no-store' });
            if (!response.ok) return;
            const config = await response.json();
            sitekey = config && config.turnstileSitekey;
        } catch {
            return;
        }
    }

    if (!sitekey || sitekey === 'REPLACE_WITH_TURNSTILE_SITEKEY') return;
    widgets.forEach(widget => { widget.dataset.sitekey = sitekey; });

    const script = document.createElement('script');
    script.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js';
    script.async = true;
    script.defer = true;
    document.head.append(script);
}

function initPageFeatures() {
    initGlobalServicesMenu();
    initFAQ();
    initServiceModals();
    initTurnstile();
    initContactForm();
    initSidebarNav();
    initTestimonialFilters();
    updateCopyrightYear();
    scheduleNetworkCanvasInit();
}

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initPageFeatures, { once: true });
} else {
    initPageFeatures();
}
